import { NgIf, NgStyle } from '@angular/common';
import {
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  Output,
  ViewEncapsulation,
  booleanAttribute,
  forwardRef,
  inject,
} from '@angular/core';
import { ControlValueAccessor, NG_VALUE_ACCESSOR } from '@angular/forms';
import { dropdownAnimations } from '@questrade/allspark-angular-components/core/animations';
import { ENTER, SPACE, voidFn } from '@questrade/allspark-angular-components/core/utils';
import { QIconComponent, QIconRegistryService } from '@questrade/allspark-angular-components/icon';
import { check, dropArrowDown, dropArrowUp } from '@questrade/allspark-icons/icons';
import { QChipChangeEvent } from './types/chip-change-event.interface';
import { QChipCheckVariant } from './types/chip-check-variant.type';
import { QChipIconPosition } from './types/chip-icon-position.type';
import { QChipTextStyle } from './types/chip-text-style.type';
import { QChipVariant } from './types/chip-variant.type';

@Component({
  imports: [QIconComponent, NgStyle, NgIf],
  selector: 'q-chip',
  templateUrl: './chip.component.html',
  styleUrls: ['./chip.component.scss'],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QChipComponent),
      multi: true,
    },
  ],
  animations: [dropdownAnimations.triggerRotate],
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    'role': 'button',
    '[attr.aria-pressed]': '_isSelectable ? active : null',
    '[attr.aria-disabled]': 'disabled || null',
    '[class]': 'classNames',
    '[class.q-chip-selectable]': '_isSelectable',
    '[class.q-chip-error]': 'error',
    '[class.q-chip-icon]': 'isIconChip',
    '[class.q-chip-active]': 'active',
    '[class.q-chip-disabled]': 'disabled',
    '[class.q-chip-readonly]': 'readonly',
    '[class.q-chip-is-dropdown]': 'isDropdown',
    '[class.q-chip-has-left-icon]': 'hasLeftIcon && !isIconChip',
    '[class.q-chip-has-right-icon]': 'hasRightIcon && !isIconChip',
    '[tabindex]': 'disabled ? -1 : 0',
    '(click)': '_onElementClick($event)',
    '(keypress)': '_onKeyPress($event)',
  },
  encapsulation: ViewEncapsulation.None,
})
export class QChipComponent<T> implements ControlValueAccessor {
  @Output() readonly changed = new EventEmitter<QChipChangeEvent<T>>();
  @Output() readonly iconClicked = new EventEmitter<string>();

  @Input({ transform: booleanAttribute }) isIconChip = false;
  @Input() toggleActiveIconColor: string | null = null;
  @Input({ transform: booleanAttribute }) toggleOnClick = true;
  @Input({ transform: booleanAttribute }) isDropdown = false;
  @Input({ transform: booleanAttribute }) error = false;
  @Input({ transform: booleanAttribute }) readonly = false;
  @Input() value: T | null = null;
  @Input() iconPosition: QChipIconPosition = 'left';
  @Input() textStyle: QChipTextStyle = 'primary';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-chip';

  @Input() set type(value: QChipVariant) {
    this._type = value;
    this._applyChanges();
  }
  get type(): QChipVariant {
    return this._type;
  }

  @Input() set showCheckIcon(value: boolean) {
    this._showCheckIcon = value;
    this._applyChanges();
  }
  get showCheckIcon(): boolean {
    return this._showCheckIcon;
  }

  @Input() set checkType(value: QChipCheckVariant) {
    this._checkType = value;
    this._applyChanges();
  }
  get checkType(): QChipCheckVariant {
    return this._checkType;
  }

  @Input() set active(value: boolean) {
    this.setActiveValue(value);
  }
  get active(): boolean {
    return this._active;
  }

  @Input() set toggleActiveIcon(value: string) {
    if (!value) return;
    this._toggleActiveIcon = value;
  }

  get _toggleActiveIconName(): string {
    if (!this._toggleActiveIcon) {
      return this._iconName;
    }
    return this._toggleActiveIcon;
  }

  @Input() set disabled(value: boolean) {
    this._disabled = value;
  }
  get disabled(): boolean {
    return this._disabled;
  }

  @Input() set icon(value: string) {
    if (value) {
      this._iconName = value;
      this._setShowIcon(this._iconName);
    } else {
      this._iconName = '';
      this._setShowIcon('');
    }
  }

  @Input() get toggleRightIcon(): string {
    return this._toggleRightIcon;
  }
  set toggleRightIcon(value: string) {
    if (value && this.checkType === 'toggle') {
      this._toggleRightIcon = value;
    } else {
      this._toggleRightIcon = '';
    }
  }

  _isMultipleCheckTypeAndNotText = false;
  _iconStyles = {};
  _textStyles = {};
  _isSelectable = false;
  _showIconName = '';
  _iconName = '';
  _toggleRightIcon = '';
  _toggleActiveIcon = '';
  _active = false;
  _type: QChipVariant = 'regular';
  _checkType: QChipCheckVariant = 'none';
  _disabled = false;
  _showCheckIcon = true;

  private _onChange: (_: boolean) => void = voidFn;
  private _onTouch: () => void = voidFn;
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _iconRegistry = inject(QIconRegistryService);

  constructor() {
    this._iconRegistry.registerIcons([check, dropArrowDown, dropArrowUp]);
  }

  /** @hidden */
  writeValue(value: boolean): void {
    this.setActiveValue(value);
  }

  /** @hidden */
  registerOnChange(fn: (_: boolean) => void): void {
    this._onChange = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => void): void {
    this._onTouch = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
    this._cdr.markForCheck();
  }

  /** @hidden */
  setActiveValue(value: boolean): void {
    this._active = value;

    if (this.checkType === 'toggle' && this.active) {
      this._setShowIcon('');

      if (this.toggleActiveIconColor) {
        this._iconStyles = {
          fill: this.toggleActiveIconColor,
        };
      }
    } else {
      this._setShowIcon(this._iconName);
      this._iconStyles = {};
    }

    this._cdr.markForCheck();
  }

  _onIconClick(iconName: string): void {
    this.iconClicked.emit(iconName);
  }

  _onElementClick(event: Event): void {
    this._toggle(event);
  }

  _onKeyPress(event: KeyboardEvent): void {
    if ([ENTER, SPACE].includes(event.code)) {
      this._toggle(event);
    }
  }

  get classNames(): string {
    return `q-chip q-chip-${this.type} q-chip-check-${this.checkType} q-focus-indicator`;
  }

  get hasLeftIcon(): boolean {
    return (
      (!!this._iconName && this.iconPosition === 'left') ||
      (this._isMultipleCheckTypeAndNotText && this.active)
    );
  }

  get hasRightIcon(): boolean {
    return (!!this._iconName && this.iconPosition === 'right') || !!this._toggleRightIcon;
  }

  private _setShowIcon(value: string): void {
    if (this.checkType === 'toggle' && this.active) {
      this._showIconName = this._toggleActiveIconName;
    } else {
      this._showIconName = value;
    }
  }

  private _applyChanges(): void {
    this._isMultipleCheckTypeAndNotText = false;
    this._isSelectable = this.checkType !== 'none';

    if (this.checkType === 'multiple' && this.type !== 'text' && this.showCheckIcon) {
      this._isMultipleCheckTypeAndNotText = true;
    }

    this._cdr.markForCheck();
  }

  private _toggle(event: Event): void {
    if (!this.toggleOnClick || this.readonly) {
      return;
    }

    const active = !this.active;

    this.changed.emit({
      active,
      value: this.value,
      nativeEvent: event,
    });

    this.setActiveValue(active);

    this._onChange(active);
    this._onTouch();
  }
}
